<?php session_start(); require __DIR__.'/../includes/db.php'; if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;} ?>
<?php $id=(int)($_GET['id']??0);$st=mysqli_prepare($conn,"SELECT * FROM products WHERE id=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($st));if(!$p)die('Product not found');if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];$category=$_POST['category'];$image=trim($_POST['image']);$description=trim($_POST['description']);$st=mysqli_prepare($conn,"UPDATE products SET name=?,price=?,stock=?,category=?,image=?,description=? WHERE id=?");mysqli_stmt_bind_param($st,'sdisssi',$name,$price,$stock,$category,$image,$description,$id);mysqli_stmt_execute($st);header('Location: products.php');exit;} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Edit Product</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include __DIR__.'/../includes/admin_navbar.php';?><main class="admin-main"><h1>Edit Product</h1><form method="POST" class="form-card"><label>Name</label><input name="name" value="<?php echo htmlspecialchars($p['name']??'');?>" required><label>Price (BDT)</label><input type="number" name="price" min="0" step="0.01" value="<?php echo htmlspecialchars($p['price']??'');?>" required><label>Stock</label><input type="number" name="stock" min="0" value="<?php echo htmlspecialchars($p['stock']??'0');?>" required><label>Category</label><select name="category" required><?php foreach(['fashion','electronics','home','beauty'] as $c): ?><option value="<?php echo $c;?>" <?php echo (($p['category']??'')===$c?'selected':'');?>><?php echo ucfirst($c);?></option><?php endforeach;?></select><label>Image Path</label><input name="image" value="<?php echo htmlspecialchars($p['image']??'images/hero_section.png');?>" required><label>Description</label><textarea name="description"><?php echo htmlspecialchars($p['description']??'');?></textarea><button type="submit">Save Product</button></form></main></body></html>